for(let k=0;k<10;k++){let s=Math.pow(.78,k),y=vy+h*.8*s;c.strokeStyle='#9c84552a';c.beginPath();c.moveTo(vx-w*.65*s,y);c.lineTo(vx+w*.65*s,y);c.stroke();c.beginPath();c.ellipse(vx,vy,Math.max(1,w*.65*s),Math.max(1,h*.46*s),0,Math.PI,2*Math.PI);c.stroke()}
