function mountEye(){let host=document.querySelector('.art');if(!host)return;host.innerHTML='<svg class="eye-art" viewBox="0 0 300 190" aria-hidden="true"><defs><radialGradient id="iris"><stop stop-color="#e9dfc6"/><stop offset=".25" stop-color="#b3bf8e"/><stop offset=".75" stop-color="#236b43"/><stop offset="1" stop-color="#07110d"/></radialGradient><clipPath id="eyeclip"><path d="M22 95Q150 -12 278 95Q150 202 22 95Z"/></clipPath></defs><g fill="none" stroke="#c9a35a" opacity=".55"><ellipse cx="150" cy="95" rx="140" ry="80"/><ellipse cx="150" cy="95" rx="132" ry="72" stroke-dasharray="2 6"/></g><g id="eyelid"><path d="M22 95Q150 -12 278 95Q150 202 22 95Z" fill="#091b11" stroke="#c9a35a" stroke-width="2"/><g clip-path="url(#eyeclip)"><g id="pupil"><circle cx="150" cy="95" r="52" fill="url(#iris)"/><ellipse cx="150" cy="95" rx="13" ry="38" fill="#020805"/><circle cx="133" cy="75" r="5" fill="#e9dfc6"/></g></g></g></svg>';let p=host.querySelector('#pupil'),lid=host.querySelector('#eyelid');p.querySelector('circle').insertAdjacentHTML('afterend',Array.from({length:96},(_,i)=>{let a=i*Math.PI/48,r=19+(i%5)*1.3;return '<path d="M'+(150+r*Math.cos(a))+' '+(95+r*Math.sin(a))+' Q'+(150+36*Math.cos(a+.13))+' '+(95+36*Math.sin(a+.13))+' '+(150+50*Math.cos(a))+' '+(95+50*Math.sin(a))+'" fill="none" stroke="'+(i%3?'#79946b':'#dac08b')+'" stroke-width=".65" opacity=".55"/>'}).join(''));host.onpointermove=e=>{let b=host.getBoundingClientRect();p.setAttribute('transform','translate('+((e.clientX-b.left)/b.width-.5)*36+' '+((e.clientY-b.top)/b.height-.5)*18+')')};let timer=setInterval(()=>{if(!reduced.matches&&window.gsap)gsap.to(lid,{scaleY:.05,transformOrigin:'50% 50%',duration:.12,yoyo:true,repeat:1})},6500);let q=$('query');if(q)q.addEventListener('input',()=>{let iris=p.querySelector('circle');iris.setAttribute('r',52+Math.min(q.value.length,20)*.65)});sceneCleanup=()=>clearInterval(timer)}
