function taskEditor(i){let x=data.tasks[i]||{};modal(t('Запись хроники','Chronicle entry'),[['name',t('Название','Title'),'text',x.name||''],['date',t('Дата','Date'),'date',x.date||selected],['kind',t('Категория (экзамен, занятие, дедлайн)','Category (exam, class, deadline)'),'text',x.kind||t('Задача','Task')]],v=>{if(x===data.tasks[i])Object.assign(x,v);else data.tasks.push({...v,done:false})})}
function gradeEditor(i){let x=data.grades[i]||{};modal(t('Академическая оценка','Academic grade'),[['name',t('Предмет / работа','Subject / assessment'),'text',x.name||''],['v',t('Оценка из 100','Score out of 100'),'number',x.v??''],['w',t('Вес, %','Weight, %'),'number',x.w??100]],v=>{let score=Number(v.v),weight=Number(v.w);if(!Number.isFinite(score)||score<0||score>100||!Number.isFinite(weight)||weight<=0||weight>100){alert(t('Оценка 0–100, вес больше 0 и не больше 100.','Score 0–100, weight above 0 and at most 100.'));return false}let row={name:v.name,v:score,w:weight};if(data.grades[i])Object.assign(data.grades[i],row);else data.grades.push(row)})}
