function weekly(){let days=Array.from({length:7},(_,i)=>{let d=new Date();d.setDate(d.getDate()-6+i);let k=day(d);return {label:d.toLocaleDateString(data.lang,{weekday:'short'}),n:data.focusLog.filter(x=>x===k).length*25,active:data.activity.includes(k)}});let max=Math.max(25,...days.map(d=>d.n));return '<div class="week-chart">'+days.map(d=>'<div><span class="week-value">'+d.n+'</span><div class="week-column"><i style="height:'+Math.max(d.active?5:0,d.n/max*100)+'%"></i></div><small>'+esc(d.label)+'</small></div>').join('')+'</div><p class="muted">'+t('Минуты завершённых фокус-сессий за последние 7 дней','Completed focus minutes over the last 7 days')+'</p>'}
function searchArchive(){let target=$('results');if(!target)return;let q=archiveQuery.trim().toLowerCase();if(!q){target.innerHTML='<p class="muted">'+t('Поиск по локальным конспектам, карточкам и задачам.','Search local notes, cards and tasks.')+'</p>';return}let items=[];data.courses.forEach((c,i)=>{c.notes.forEach((n,j)=>items.push({type:'notes',label:c.name+' · '+n.title,body:String(n.body||''),action:'result:'+i+':'+j}));c.cards.forEach(k=>items.push({type:'cards',label:c.name+' · '+k.q,body:String(k.a||''),action:'course:'+i}))});data.tasks.forEach(x=>items.push({type:'tasks',label:x.name,body:(x.kind||'')+' · '+x.date,action:'jumpDate:'+x.date}));let matches=items.filter(x=>(archiveFilter==='all'||archiveFilter===x.type)&&(x.label+' '+x.body).toLowerCase().includes(q));function highlight(s){s=String(s);let i=s.toLowerCase().indexOf(q);if(i<0)return esc(s.slice(0,140));let a=Math.max(0,i-45),b=Math.min(s.length,i+q.length+90);return (a?'…':'')+esc(s.slice(a,i))+'<mark>'+esc(s.slice(i,i+q.length))+'</mark>'+esc(s.slice(i+q.length,b))+(b<s.length?'…':'')}target.innerHTML='<p class="eyebrow">'+t('Найдено','Matches')+' · '+matches.length+'</p>'+matches.map(x=>'<button class="search-result" data-open="'+esc(x.action)+'"><strong>'+highlight(x.label)+'</strong><span>'+highlight(x.body)+'</span><small>'+t('Открыть','Open')+' ↗</small></button>').join('');target.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{let [a,v,w]=b.dataset.open.split(':');if(a==='course'){route=1;course=Number(v);note=-1}else if(a==='result'){route=1;course=Number(v);note=Number(w)}else{route=2;selected=v;month=new Date(v+'T12:00:00')}render();scrollTo(0,0)})}
