if(route===0){let unread=data.courses.flatMap((c,i)=>c.notes.map((n,j)=>({c,i,n,j}))).find(x=>!x.n.read),due=data.courses.flatMap(c=>c.cards).filter(k=>!k.due||k.due<=day()).length,late=data.tasks.filter(x=>!x.done&&x.date<day()).length;let s=section(t('Сегодня','Today'),'<div class="action-list">'+(unread?button(t('Продолжить: ','Continue: ')+unread.n.title,'result:'+unread.i+':'+unread.j,'action-tile'):button(t('Открыть библиотеку','Open library'),'route:1','action-tile'))+button(t('Начать фокус-сессию · 25 мин','Start focus · 25 min'),'focusNow','action-tile')+button(t('Карточки к повторению · ','Cards due · ')+due,'route:3','action-tile')+button(t('Календарь · просрочено ','Calendar · overdue ')+late,'route:2','action-tile')+'</div>');p.querySelector('.stats')?.after(s)}
