async function copyManuscript(){let n=data.courses[course]?.notes[note];if(!n)return;try{await navigator.clipboard.writeText(n.title+'\n\n'+n.body);toast(t('Конспект скопирован','Note copied'))}catch{toast(t('Не удалось скопировать. Выдели текст вручную.','Copy unavailable. Select the text manually.'))}}
