function restoreArchive(){let input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{let file=input.files[0];if(!file)return;try{if(file.size>5000000)throw Error('size');let v=JSON.parse(await file.text());if(!v||!Array.isArray(v.courses)||!Array.isArray(v.tasks)||!v.courses.every(c=>c&&typeof c.name==='string'&&Array.isArray(c.notes)&&Array.isArray(c.cards)&&c.notes.every(n=>n&&typeof n.title==='string'&&typeof n.body==='string')&&c.cards.every(k=>k&&typeof k.q==='string'&&typeof k.a==='string'))||!v.tasks.every(x=>x&&typeof x.name==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(x.date)))throw Error('format');if(!confirm(t('Заменить локальные данные содержимым архива? Сначала можно отменить и экспортировать текущие данные.','Replace local data with this archive? Cancel to export your current data first.')))return;let next={...v,lang:v.lang==='en'?'en':'ru',grades:Array.isArray(v.grades)?v.grades.filter(g=>g&&typeof g.name==='string'):[],activity:Array.isArray(v.activity)?v.activity.filter(x=>typeof x==='string'):[],plan:Array.isArray(v.plan)?v.plan.filter(x=>x&&Number.isInteger(x.step)&&x.step>=0&&x.step<4&&Number.isFinite(x.minutes)):[],focusLog:Array.isArray(v.focusLog)?v.focusLog.filter(x=>typeof x==='string'):[],timer:{seconds:1500,end:0}};let raw=JSON.stringify(next);localStorage.setItem('codex',raw);data=next;seconds=1500;end=0;route=0;course=note=-1;review=null;render();toast(t('Архив восстановлен','Archive restored'))}catch{toast(t('Не удалось прочитать архив. Проверь формат и размер файла.','Could not read the archive. Check format and size.'))}};input.click()}
function commandPalette(){let d=$('modal');$('modalTitle').textContent=t('Быстрый переход','Quick access');$('fields').innerHTML='<div class="command-list">'+names().map((n,i)=>'<button type="button" data-cmd="'+i+'">'+medallion(i)+'<span>'+n+'</span><small>0'+(i+1)+'</small></button>').join('')+'</div>';$('save').hidden=true;$('cancel').textContent=t('Закрыть','Close');$('fields').querySelectorAll('[data-cmd]').forEach(b=>b.onclick=()=>{d.close();go(Number(b.dataset.cmd))});d.addEventListener('close',()=>$('save').hidden=false,{once:true});d.showModal()}
