if(route===0){let stats=p.querySelector('.stats');if(stats){let upcoming=data.tasks.filter(x=>!x.done).sort((a,b)=>String(a.date).localeCompare(String(b.date)))[0],all=data.courses.reduce((s,c)=>s+c.notes.length,0),read=data.courses.reduce((s,c)=>s+c.notes.filter(n=>n.read).length,0);let block=document.createElement('section');block.className='daily-brief';block.innerHTML='<div class="brief-left"><small>'+t('Учебная готовность','Reading progress')+'</small><strong>'+Math.round(read/Math.max(1,all)*100)+'<sup>%</sup></strong><span>'+read+' / '+all+' '+t('конспектов','notes')+'</span></div><div class="brief-right"><small>'+t('Ближайшая задача','Next task')+'</small>'+(upcoming?'<button data-act="jumpDate:'+esc(upcoming.date)+'"><strong>'+esc(upcoming.name)+'</strong><span>'+esc(upcoming.date)+' ↗</span></button>':'<button data-act="addTask">'+t('Добавить задачу','Add task')+' ↗</button>')+'</div>';stats.after(block)}let last=data.lastRead,n=last&&data.courses[last.course]?.notes[last.note];if(n){let tile=p.querySelector('.action-list .action-tile');if(tile){tile.dataset.act='result:'+last.course+':'+last.note;tile.textContent=t('Продолжить: ','Resume: ')+n.title}}}
if(route===1&&course>=0){let c=data.courses[course];if(!c)return;if(note>=0&&c.notes[note]){let n=c.notes[note],reader=p.querySelector('.reader');if(reader){let bar=document.createElement('div');bar.className='reader-toolbar';bar.innerHTML=button(n.pinned?t('★ Закреплено','★ Pinned'):t('☆ Закрепить','☆ Pin'),'pinNote')+button(t('Копировать','Copy'),'copyNote');reader.before(bar);let count=String(n.body).trim().split(/\s+/).filter(Boolean).length;reader.insertAdjacentHTML('afterbegin','<p class="reading-meta">'+count+' '+t('слов','words')+' · '+Math.max(1,Math.ceil(count/200))+' '+t('мин чтения','min read')+'</p>')}}else{let head=p.querySelectorAll('h2')[0];if(head)head.insertAdjacentHTML('afterend','<div class="volume-actions">'+button(t('Переименовать том','Rename volume'),'renameCourse')+'</div>');let rows=p.querySelectorAll('.entry');let cardRows=Array.from(rows).slice(c.notes.length);cardRows.forEach((row,i)=>{row.insertAdjacentHTML('beforeend',button(t('Изменить','Edit'),'editCard:'+i))});Array.from(rows).slice(0,c.notes.length).forEach((row,i)=>{if(c.notes[i].pinned)row.classList.add('pinned-note')})}}
